const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const C = JSON.parse(await fs.readFile(S+"\\_GIG_CLEAN_FINAL.json","utf8"));

const all = [];
for (const [cat, items] of Object.entries(C.groups)) for (const it of items) all.push({...it, cat});
const aLevel = all.filter(x=>x.group==="能看到活");
const bLevel = all.filter(x=>x.group!=="能看到活");

// A级里，有多少是「cards=0」的（即只有价格信号没有项目卡片）
const weakA = aLevel.filter(x=>!x.cards || x.cards===0);
const strongA = aLevel.filter(x=>x.cards && x.cards>0);

return {
  total: all.length,
  aLevel: aLevel.length,
  bLevel: bLevel.length,
  strongA: strongA.length,
  weakA: weakA.length,
  weakList: weakA.map(x=>x.name+" ("+x.host+") "+x.verdict)
};
